97	static void layer_surface_configure(void *data,
98	                                    struct zwlr_layer_surface_v1 *surface,
99	                                    uint32_t serial, uint32_t width,
100	                                    uint32_t height) {
101	  auto monitor = static_cast<Monitor *>(data);
102	  monitor->m_height = height;
103	  monitor->m_width = width;
104	  zwlr_layer_surface_v1_ack_configure(monitor->getLayerSurface(), serial);
105	  monitor->resizeEGL();
106	  if (monitor->m_glSetup == false) {
107	    monitor->setupGl();
108	    // First configure for this output: GL is live and the surface has real
109	    // dimensions, so this is the earliest moment a wallpaper can actually be
110	    // drawn. Hotplugged monitors arrive here too, which is what lets them
111	    // pick up a wallpaper without anything outside the daemon poking us.
112	    monitor->onSurfaceReady();
113	  }
114	  // monitor->createAndAttachBuffer();
115	}
