300	static float easeInOutCirc(float x) {
301	  x = std::clamp(x, 0.0f, 1.0f);
302	  return x < 0.5f
303	             ? (1.0f - std::sqrt(1.0f - std::pow(2.0f * x, 2.0f))) / 2.0f
304	             : (std::sqrt(1.0f - std::pow(-2.0f * x + 2.0f, 2.0f)) + 1.0f) /
305	                   2.0f;
306	}
307	void Monitor::resumeTransition() {
308	  GLuint transition = m_requiredTransitionShaderProgram;
309	  glUseProgram(transition);
310	  glActiveTexture(GL_TEXTURE0);
311	  glBindTexture(GL_TEXTURE_2D, m_textures[0]);
312	  glActiveTexture(GL_TEXTURE1);
313	  glBindTexture(GL_TEXTURE_2D, m_textures[1]);
314	  glActiveTexture(GL_TEXTURE2);
315	  glBindTexture(GL_TEXTURE_2D, m_toTextures[0]);
316	  glActiveTexture(GL_TEXTURE3);
317	  glBindTexture(GL_TEXTURE_2D, m_toTextures[1]);
318	
319	  glUniform1i(glGetUniformLocation(transition, "uTexY_from"), 0);
320	  glUniform1i(glGetUniformLocation(transition, "uTexC_from"), 1);
321	  glUniform1i(glGetUniformLocation(transition, "uTexY_to"), 2);
322	  glUniform1i(glGetUniformLocation(transition, "uTexC_to"), 3);
323	  glUniform1f(glGetUniformLocation(transition, "ratio"),
324	              (static_cast<float>(m_bufferWidth) / m_bufferHeight));
325	
326	  glUniform2f(glGetUniformLocation(m_glShaderProgram, "uTexCoordScale"),
327	              m_lastTextCoordScaleX, m_lastTextCoordScaleY);
328	  auto now = std::chrono::steady_clock::now();
329	  float progress =
330	      std::chrono::duration<float>(now - m_transitionState->m_startTime) /
331	      m_transitionState->m_duration;
332	  progress = std::clamp(progress, 0.0f, 1.0f);
333	  // float easedProgress = easeInOutCirc(progress);
334	  glUniform1f(glGetUniformLocation(transition, "progress"), progress);
335	  glViewport(0, 0, static_cast<GLsizei>(m_bufferWidth),
336	             static_cast<GLsizei>(m_bufferHeight));
337	  m_daemon.glBindVertexArray(m_VAO);
338	  glClear(GL_COLOR_BUFFER_BIT);
339	  glDrawElements(GL_TRIANGLES, 6, GL_UNSIGNED_INT, 0);
340	  if (eglSwapBuffers(m_daemon.m_eglDisplay, m_eglSurface) != EGL_TRUE) {
341	    std::cout << eglGetError() << std::endl;
342	    throw std::runtime_error("eglSwapBuffers failed");
343	  }
344	  if (progress >= 1.0f) {
345	    m_transitionState = nullptr;
346	    // Refresh the from-texture once after the transition completes so future
347	    // transitions don't start from a stale frame. Static images stop
348	    // scheduling frame callbacks after m_transitionState is cleared, so
349	    // this one render() call is needed to update the texture.
350	    if (m_wallpaper->m_isSingleFrame) {
351	      render();
352	    }
353	  }
354	}
