385	void Monitor::renderSoftwareNV12() {
386	  auto *frame = m_wallpaper->m_frame;
387	  int width = frame->width;
388	  int height = frame->height;
389	
390	  stageNV12Buffers(width, height);
391	  glUseProgram(m_glShaderProgram);
392	  glUniform1i(glGetUniformLocation(m_glShaderProgram, "uTexY"), 0);
393	  glUniform1i(glGetUniformLocation(m_glShaderProgram, "uTexC"), 1);
394	  glUniform2f(glGetUniformLocation(m_glShaderProgram, "uTexCoordScale"), 1.0f,
395	              1.0f);
396	  m_lastTextCoordScaleX = 1.0f;
397	  m_lastTextCoordScaleY = 1.0f;
398	
399	  m_daemon.glBindVertexArray(m_VAO);
400	  // Y plane
401	  glActiveTexture(GL_TEXTURE0);
402	  glBindTexture(GL_TEXTURE_2D,
403	                m_renderIntoTempTexture ? m_toTextures[0] : m_textures[0]);
404	  glPixelStorei(GL_UNPACK_ROW_LENGTH, frame->linesize[0]);
405	  glTexSubImage2D(GL_TEXTURE_2D, 0, 0, 0, width, height, GL_RED,
406	                  GL_UNSIGNED_BYTE, frame->data[0]);
407	
408	  // UV plane
409	  glActiveTexture(GL_TEXTURE1);
410	  glBindTexture(GL_TEXTURE_2D,
411	                m_renderIntoTempTexture ? m_toTextures[1] : m_textures[1]);
412	  glPixelStorei(GL_UNPACK_ROW_LENGTH, frame->linesize[1] / 2);
413	  glTexSubImage2D(GL_TEXTURE_2D, 0, 0, 0, width / 2, height / 2, GL_RG,
414	                  GL_UNSIGNED_BYTE, frame->data[1]);
415	
416	  glPixelStorei(GL_UNPACK_ROW_LENGTH, 0);
417	
418	  if (!m_renderIntoTempTexture) {
419	    glClear(GL_COLOR_BUFFER_BIT);
420	    glDrawElements(GL_TRIANGLES, 6, GL_UNSIGNED_INT, 0);
421	    if (eglSwapBuffers(m_daemon.m_eglDisplay, m_eglSurface) != EGL_TRUE) {
422	      std::cout << eglGetError() << std::endl;
423	      throw std::runtime_error("eglSwapBuffers failed");
424	    }
425	  }
426	}
