429	void Monitor::renderCUDACopy() {
430	  cudaNV12GLUpload(m_wallpaper->m_frame);
431	
432	  glUseProgram(m_glShaderProgram);
433	  glUniform1i(glGetUniformLocation(m_glShaderProgram, "uTexY"), 0);
434	  glUniform1i(glGetUniformLocation(m_glShaderProgram, "uTexC"), 1);
435	  glUniform2f(glGetUniformLocation(m_glShaderProgram, "uTexCoordScale"), 1.0f,
436	              1.0f);
437	  m_lastTextCoordScaleX = 1.0;
438	  m_lastTextCoordScaleY = 1.0;
439	  m_daemon.glBindVertexArray(m_VAO);
440	
441	  glActiveTexture(GL_TEXTURE0);
442	  glBindTexture(GL_TEXTURE_2D, m_renderIntoTempTexture
443	                                   ? m_toTextures[0]
444	                                   : m_textures[0]); // Y -> uTexY
445	  glActiveTexture(GL_TEXTURE1);
446	  glBindTexture(GL_TEXTURE_2D, m_renderIntoTempTexture
447	                                   ? m_toTextures[1]
448	                                   : m_textures[1]); // UV -> uTexC
449	
450	  if (!m_renderIntoTempTexture) {
451	    glClear(GL_COLOR_BUFFER_BIT);
452	    glDrawElements(GL_TRIANGLES, 6, GL_UNSIGNED_INT, 0);
453	
454	    if (eglSwapBuffers(m_daemon.m_eglDisplay, m_eglSurface) != EGL_TRUE) {
455	      std::cout << eglGetError() << std::endl;
456	      throw std::runtime_error("eglSwapBuffers failed");
457	    }
458	  }
459	}
460	void Monitor::cudaNV12GLUpload(AVFrame *frame) {
461	  int width = frame->width;
462	  int height = frame->height;
463	  stageNV12Buffers(width, height);
464	  m_wallpaper->makeCudaContextCurrent();
465	  {
466	    CUDA_MEMCPY2D copy = {};
467	    copy.srcMemoryType = CU_MEMORYTYPE_DEVICE;
468	    copy.srcDevice = reinterpret_cast<CUdeviceptr>(frame->data[0]);
469	    copy.srcPitch = frame->linesize[0];
470	
471	    copy.dstMemoryType = CU_MEMORYTYPE_HOST;
472	    copy.dstHost = m_hostY.data();
473	    copy.dstPitch = width;
474	
475	    copy.WidthInBytes = width;
476	    copy.Height = height;
477	    CUresult res = cuMemcpy2D(&copy);
478	    if (res != CUDA_SUCCESS) {
479	      const char *errName = nullptr;
480	      const char *errStr = nullptr;
481	      cuGetErrorName(res, &errName);
482	      cuGetErrorString(res, &errStr);
483	      std::cerr << "cuMemcpy2D (Y plane) failed: "
484	                << (errName ? errName : "unknown") << " - "
485	                << (errStr ? errStr : "no description") << std::endl;
486	      throw std::runtime_error("CUDA memcopy of Y plane failed");
487	    }
488	  }
489	  {
490	    CUDA_MEMCPY2D copy = {};
491	    copy.srcMemoryType = CU_MEMORYTYPE_DEVICE;
492	    copy.srcDevice = reinterpret_cast<CUdeviceptr>(frame->data[1]);
493	    copy.srcPitch = frame->linesize[1];
494	    copy.dstMemoryType = CU_MEMORYTYPE_HOST; // <-- fixed
495	    copy.dstHost = m_hostUV.data();
496	    copy.dstPitch = width;
497	    copy.WidthInBytes = width;
498	    copy.Height = height / 2;
499	    CUresult res = cuMemcpy2D(&copy);
500	    if (res != CUDA_SUCCESS) {
501	      const char *errName = nullptr;
502	      const char *errStr = nullptr;
503	      cuGetErrorName(res, &errName);
504	      cuGetErrorString(res, &errStr);
505	      std::cerr << "cuMemcpy2D (UV plane) failed: "
506	                << (errName ? errName : "unknown") << " - "
507	                << (errStr ? errStr : "no description") << std::endl;
508	      throw std::runtime_error("CUDA memcopy of UV plane failed");
509	    }
510	  }
511	  glBindTexture(GL_TEXTURE_2D,
512	                m_renderIntoTempTexture ? m_toTextures[0] : m_textures[0]);
513	  glTexSubImage2D(GL_TEXTURE_2D, 0, 0, 0, width, height, GL_RED,
514	                  GL_UNSIGNED_BYTE, m_hostY.data());
515	
516	  glBindTexture(GL_TEXTURE_2D, m_renderIntoTempTexture == true ? m_toTextures[1]
517	                                                               : m_textures[1]);
518	  glTexSubImage2D(GL_TEXTURE_2D, 0, 0, 0, width / 2, height / 2, GL_RG,
519	                  GL_UNSIGNED_BYTE, m_hostUV.data());
520	
521	  glBindTexture(GL_TEXTURE_2D, 0);
522	}
