704	void Monitor::onScaleChanged() {
705	
706	  if (m_waylandSurface == nullptr || m_layerSurface == nullptr)
707	    return;
708	
709	  setBufferSize();
710	
711	  if (m_viewport) {
712	    wp_viewport_set_destination(m_viewport, m_width, m_height);
713	  } else {
714	    wl_surface_set_buffer_scale(m_waylandSurface, m_scale);
715	  }
716	
717	  if (m_eglWindow != nullptr) {
718	    wl_egl_window_resize(m_eglWindow, static_cast<int>(m_bufferWidth),
719	                         static_cast<int>(m_bufferHeight), 0, 0);
720	    if (eglMakeCurrent(m_daemon.m_eglDisplay, m_eglSurface, m_eglSurface,
721	                       m_daemon.m_eglContext) == EGL_TRUE) {
722	      glViewport(0, 0, static_cast<GLsizei>(m_bufferWidth),
723	                 static_cast<GLsizei>(m_bufferHeight));
724	    }
725	  }
726	  wl_surface_commit(m_waylandSurface);
727	}
